/**
 * 本文件由 scripts/build.mjs 生成，请勿手工编辑。
 * 修改样式请编辑 src/client/styles.css，然后运行 `node scripts/build.mjs`。
 */
export const STYLES = "/*\n * 余额徽章 —— 样式表。\n *\n * 视觉目标是「看起来像宿主自己画的」：徽章沿用 ContextMeter 触发器与\n * StatsPills 胶囊的同一套尺寸（13px 字号、20px 行高、1px 8px 内边距、\n * tabular-nums），展开面板沿用宿主统计气泡面板的同一套表面与阴影令牌。\n * 唯一新增的是档位配色：正常绿、偏低橙、不足红。\n */\n\n/*\n * 档位色定义在 `:root` 上，而不是只挂在 `.dbp_root` 上。\n *\n * 原因：展开面板是 portal 到 `document.body` 的，**不在 `.dbp_root` 子树里** ——\n * 只在徽章上定义这三个变量，面板里的 `var(--dbp-warn)` 就会解析失败，而\n * `color-mix(in srgb, var(--x) 14%, transparent)` 在变量无效时整条声明被丢弃，\n * SVG 于是回落到继承色（黑板一样的黑色）。这在 v1.2 画趋势图时暴露出来。\n *\n * 挂到 `:root` 后徽章与面板共享同一份定义；`body[data-ds-dark-theme]` 的覆盖\n * 本来就在根级，优先级仍然正确。\n */\n:root {\n  /* 档位色：优先用主题令牌，令牌缺失时回落到自带色值。 */\n  --dbp-ok: var(--dsw-alias-state-success-primary, #1f8f5f);\n  --dbp-warn: #c07a12;\n  --dbp-low: var(--dsw-alias-state-error-primary, #d93a45);\n  /*\n   * 时段色（v1.3）：高峰 = 贵，用暖色；空闲 = 便宜，用绿色。\n   *\n   * 同样必须定义在 `:root` 上：面板 portal 到 `body`，`.dbp_tariffBadge` 不在\n   * `.dbp_root` 子树里，把变量挂在徽章上会让面板里的 `var()` 解析失败。\n   */\n  --dbp-peak: #c07a12;\n  --dbp-offpeak: var(--dsw-alias-state-success-primary, #1f8f5f);\n  /*\n   * 视觉升级（v0.4）新增的四个中性令牌。它们只描述「表面 / 发丝线 / 轨道 / 阴影」，\n   * 不引入新的语义色 —— 颜色仍然全部来自档位与时段两组变量，避免面板里出现\n   * 第二套配色体系。同样挂在 `:root` 上（面板 portal 到 body）。\n   */\n  --dbp-surface: color-mix(in srgb, var(--dsw-alias-label-tertiary) 5%, transparent);\n  --dbp-hairline: var(--dsw-alias-border-l1);\n  --dbp-rail: color-mix(in srgb, var(--dsw-alias-label-tertiary) 26%, transparent);\n  --dbp-panel-border: var(--dsw-alias-border-l1);\n}\n\nbody[data-ds-dark-theme] {\n  --dbp-ok: #4bbf8b;\n  --dbp-warn: #e2a13c;\n  --dbp-low: #f06a6a;\n  --dbp-peak: #e2a13c;\n  --dbp-offpeak: #4bbf8b;\n  /* 深色下 5% 的黑几乎不可见，表面改为「提亮」而不是「压暗」。 */\n  --dbp-surface: color-mix(in srgb, #ffffff 6%, transparent);\n  --dbp-rail: color-mix(in srgb, #ffffff 18%, transparent);\n  --dbp-panel-border: color-mix(in srgb, #ffffff 9%, transparent);\n}\n\n.dbp_root {\n  /* 行内顺序：宿主两个统计胶囊是 order 0，上下文环（ContextMeter）也是 0，\n     这里用 order:1 把自己排到它们右侧，即整行末尾。 */\n  order: 1;\n  flex: none;\n  display: inline-flex;\n}\n\n.dbp_trigger {\n  box-sizing: border-box;\n  border: none;\n  background: 0 0;\n  /* 胶囊形：状态行里的其他条目是圆角矩形，徽章做成胶囊才能在视觉上「自成一枚」。 */\n  padding: 2px 9px;\n  border-radius: 999px;\n  font-family: inherit;\n  font-size: var(--dsh-content-font-size-secondary, 13px);\n  font-variant-numeric: tabular-nums;\n  line-height: calc(20px + var(--dsh-content-font-delta-secondary, 0px));\n  white-space: nowrap;\n  cursor: pointer;\n  flex: none;\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  color: var(--dsw-alias-label-tertiary);\n  transition: color 0.15s ease, background-color 0.15s ease, box-shadow 0.15s ease;\n}\n\n.dbp_trigger:focus-visible {\n  outline: 2px solid var(--dsw-focus-ring-color, var(--dsw-alias-state-business-primary));\n  outline-offset: 1px;\n}\n\n.dbp_text {\n  font-weight: 500;\n}\n\n.dbp_icon {\n  flex: none;\n  display: block;\n}\n\n/* ---------------------------------------------------------------- 档位配色 */\n\n.dbp_root[data-status='loading'] .dbp_trigger,\n.dbp_root[data-status='signed-out'] .dbp_trigger,\n.dbp_root[data-status='failed'] .dbp_trigger {\n  color: var(--dsw-alias-label-tertiary);\n}\n\n/* ready 与 stale 用同一套档位色：stale 只是「这个数字可能过期」，\n   颜色仍然表达余额本身的高低，否则一次网络抖动会让红色警示凭空消失。 */\n.dbp_root[data-level='ok'][data-status='ready'] .dbp_trigger,\n.dbp_root[data-level='ok'][data-status='stale'] .dbp_trigger {\n  color: var(--dbp-ok);\n}\n\n/* 警告与不足两档：底色 + 一圈同色发丝内描边。\n   只用底色时，浅色主题下 10% 的暖色非常淡，小字号几乎看不出「这是一枚警示」；\n   内描边把边界补上，同时不改变布局尺寸（inset 不占位）。 */\n.dbp_root[data-level='warn'][data-status='ready'] .dbp_trigger,\n.dbp_root[data-level='warn'][data-status='stale'] .dbp_trigger {\n  color: var(--dbp-warn);\n  background-color: color-mix(in srgb, var(--dbp-warn) 10%, transparent);\n  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dbp-warn) 22%, transparent);\n}\n\n.dbp_root[data-level='low'][data-status='ready'] .dbp_trigger,\n.dbp_root[data-level='low'][data-status='stale'] .dbp_trigger {\n  color: var(--dbp-low);\n  background-color: color-mix(in srgb, var(--dbp-low) 12%, transparent);\n  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dbp-low) 26%, transparent);\n  font-weight: 600;\n}\n\n/* 过期态：档位色保留，但整体降一点不透明度，并给个虚线下划线，\n   让「数字还在、但不是最新」这件事在颜色之外还有第二个信号。 */\n.dbp_root[data-status='stale'] .dbp_trigger {\n  opacity: 0.78;\n}\n\n.dbp_root[data-status='stale'] .dbp_text {\n  text-decoration: underline dotted currentColor;\n  text-underline-offset: 3px;\n}\n\n.dbp_root[data-status='failed'] .dbp_trigger {\n  color: var(--dbp-warn);\n}\n\n.dbp_trigger:hover {\n  background-color: color-mix(in srgb, currentColor 14%, transparent);\n}\n\n.dbp_trigger:active {\n  background-color: color-mix(in srgb, currentColor 20%, transparent);\n}\n\n.dbp_root[data-level='low'][data-status='ready'] .dbp_trigger:hover,\n.dbp_root[data-level='low'][data-status='stale'] .dbp_trigger:hover,\n.dbp_root[data-level='warn'][data-status='ready'] .dbp_trigger:hover,\n.dbp_root[data-level='warn'][data-status='stale'] .dbp_trigger:hover {\n  background-color: color-mix(in srgb, currentColor 20%, transparent);\n}\n\n/* ---------------------------------------------------------------- 展开面板 */\n\n.dbp_panel {\n  box-sizing: border-box;\n  position: fixed;\n  z-index: 1100;\n  /* 内容随历史/时段变多；小窗口或大字号下必须自己滚动，否则顶部会被视口裁掉。\n     内联样式会再按徽章上方的实际空间收紧 max-height（见 pill.js usePanelPosition）。 */\n  max-height: calc(100vh - 24px);\n  overflow-y: auto;\n  overscroll-behavior: contain;\n  scrollbar-width: thin;\n  scrollbar-color: var(--dbp-rail) transparent;\n  padding: 14px;\n  /* 发丝边 + 阴影：浅色页面里纯阴影的卡片边界很虚，补一圈 1px 边界才立得住。 */\n  border: 1px solid var(--dbp-panel-border);\n  border-radius: 14px;\n  background: var(--dsw-specific-menu);\n  backdrop-filter: var(--dsw-menu-backdrop-filter);\n  --dsw-elevation-stroke-color: var(--dsw-alias-border-l1);\n  box-shadow: var(--dsw-elevation-prominent);\n  color: var(--dsw-alias-label-secondary);\n  font-size: 12px;\n  line-height: 20px;\n  cursor: default;\n  /* 展开动效：只做 4px 的位移与极小缩放，README 的截图对比不受影响；\n     prefers-reduced-motion 下整段关闭（见文件末尾）。 */\n  animation: dbp-panel-in 140ms cubic-bezier(0.2, 0.8, 0.3, 1) both;\n  transform-origin: bottom right;\n}\n\n@keyframes dbp-panel-in {\n  from {\n    opacity: 0;\n    transform: translateY(4px) scale(0.985);\n  }\n  to {\n    opacity: 1;\n    transform: none;\n  }\n}\n\n.dbp_panelHead {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.dbp_panelTitle {\n  color: var(--dsw-alias-label-primary);\n  font-size: 13px;\n  font-weight: 600;\n  letter-spacing: 0.01em;\n}\n\n/* 面板标题旁的版本号：诊断用，弱化成一枚小标签，不去抢标题与刷新按钮。 */\n.dbp_panelVersion {\n  flex: none;\n  padding: 0 5px;\n  border-radius: 5px;\n  background: var(--dbp-surface);\n  color: var(--dsw-alias-label-tertiary);\n  font-size: 10.5px;\n  line-height: 16px;\n  font-variant-numeric: tabular-nums;\n}\n\n.dbp_refresh {\n  box-sizing: border-box;\n  margin-left: auto;\n  padding: 0 10px;\n  height: 26px;\n  border: 1px solid var(--dbp-hairline);\n  border-radius: 8px;\n  background: 0 0;\n  color: var(--dsw-alias-label-secondary);\n  font-family: inherit;\n  font-size: 12px;\n  line-height: 22px;\n  cursor: pointer;\n  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease;\n}\n\n.dbp_refresh:hover:not(:disabled) {\n  background: var(--dsw-alias-interactive-bg-hover);\n  border-color: var(--dsw-alias-border-l3);\n  color: var(--dsw-alias-label-primary);\n}\n\n.dbp_refresh:active:not(:disabled) {\n  background: color-mix(in srgb, var(--dsw-alias-label-primary) 9%, transparent);\n}\n\n.dbp_refresh:disabled {\n  color: var(--dsw-alias-label-caption, var(--dsw-alias-label-tertiary));\n  cursor: default;\n}\n\n.dbp_refresh:focus-visible {\n  outline: 2px solid var(--dsw-focus-ring-color, var(--dsw-alias-state-business-primary));\n  outline-offset: 1px;\n}\n\n.dbp_rule {\n  height: 1px;\n  margin: 12px 0;\n  background: var(--dbp-hairline);\n}\n\n.dbp_rows {\n  display: grid;\n  grid-template-columns: 1fr auto;\n  gap: 5px 12px;\n  margin: 0;\n}\n\n.dbp_rows dt {\n  color: var(--dsw-alias-label-tertiary);\n  font-weight: 400;\n}\n\n.dbp_rows dd {\n  margin: 0;\n  text-align: right;\n  font-variant-numeric: tabular-nums;\n  color: var(--dsw-alias-label-primary);\n}\n\n/* 合计行是这个面板的主数字：字号拉开两档，行距也随之加一点，\n   让「余额是多少」在 3 秒内能被扫到，而不是和两项拆分一样重。 */\n.dbp_totalKey {\n  padding-top: 6px;\n  color: var(--dsw-alias-label-secondary) !important;\n  font-size: 12px;\n}\n\n.dbp_totalValue {\n  padding-top: 6px;\n  font-size: 19px;\n  font-weight: 650;\n  line-height: 24px;\n  letter-spacing: -0.01em;\n}\n\n.dbp_hint {\n  margin: 12px 0 0;\n  color: var(--dsw-alias-label-tertiary);\n  font-weight: 500;\n}\n\n.dbp_hint[data-level='ok'] {\n  color: var(--dbp-ok);\n}\n\n.dbp_hint[data-level='warn'] {\n  color: var(--dbp-warn);\n}\n\n.dbp_hint[data-level='low'] {\n  color: var(--dbp-low);\n}\n\n.dbp_message {\n  margin: 0;\n  color: var(--dsw-alias-label-secondary);\n}\n\n.dbp_stale {\n  margin: 0 0 10px;\n  padding: 6px 9px;\n  border-radius: 8px;\n  border-left: 2px solid var(--dbp-warn);\n  background: color-mix(in srgb, var(--dbp-warn) 11%, transparent);\n  color: var(--dbp-warn);\n  font-size: 11.5px;\n  line-height: 17px;\n}\n\n.dbp_meta {\n  margin: 1px 0 0;\n  color: var(--dsw-alias-label-tertiary);\n  font-size: 11px;\n  line-height: 17px;\n}\n\n/* ------------------------------------------------------------ 会话消耗与趋势 */\n\n/*\n * 消耗统计五行（本轮 / 今日 / 本周 / 近 7 天 / 跑道 / 最近充值）是同一族背景信息：\n * 统一成 11.5px 的紧凑列表 + 一枚 3px 圆点前缀。圆点比缩进更像「一组数据」，\n * 也让「本轮会话」的高亮底纹与其余行的关系一眼可读。\n */\n.dbp_spend,\n.dbp_today,\n.dbp_week,\n.dbp_recent,\n.dbp_topup,\n.dbp_runway {\n  position: relative;\n  margin: 1px 0 0;\n  padding-left: 12px;\n  color: var(--dsw-alias-label-tertiary);\n  font-size: 11.5px;\n  line-height: 18px;\n  font-variant-numeric: tabular-nums;\n}\n\n.dbp_spend::before,\n.dbp_today::before,\n.dbp_week::before,\n.dbp_recent::before,\n.dbp_topup::before,\n.dbp_runway::before {\n  content: '';\n  position: absolute;\n  left: 3px;\n  top: 7px;\n  width: 3px;\n  height: 3px;\n  border-radius: 50%;\n  background: currentColor;\n  opacity: 0.5;\n}\n\n/* 本轮会话：唯一带底纹的一行 —— 它是「你刚问的这件事」的直接反馈。 */\n.dbp_spend {\n  margin: 10px 0 2px;\n  padding: 6px 9px 6px 13px;\n  border-radius: 8px;\n  background: var(--dbp-surface);\n  color: var(--dsw-alias-label-secondary);\n  font-size: 12px;\n  font-weight: 500;\n}\n\n.dbp_spend::before {\n  left: 6px;\n  top: 12px;\n  opacity: 0.7;\n}\n\n/* 今日 / 本周 / 近 7 天：三层递进的统计，越远期越轻。 */\n.dbp_today {\n  color: var(--dsw-alias-label-secondary);\n}\n\n.dbp_week {\n  opacity: 0.92;\n}\n\n.dbp_recent {\n  opacity: 0.85;\n}\n\n/* 最近充值：入账是好消息，但不额外加重 —— 面板里带颜色的元素只在需要决策时出现。 */\n.dbp_topup::before {\n  background: var(--dbp-ok);\n  opacity: 0.85;\n}\n\n/* 余额跑道：预测，不是事实，视觉上比金额明细更轻。 */\n.dbp_runway {\n  opacity: 0.85;\n}\n\n.dbp_trend {\n  margin: 12px 0 0;\n  padding: 8px 8px 2px;\n  border: 1px solid var(--dbp-hairline);\n  border-radius: 10px;\n  background: var(--dbp-surface);\n}\n\n.dbp_spark {\n  display: block;\n  width: 100%;\n  height: 46px;\n  overflow: visible;\n}\n\n.dbp_sparkLine {\n  fill: none;\n  stroke: var(--dsw-alias-label-tertiary);\n  stroke-width: 1.75;\n  stroke-linejoin: round;\n  stroke-linecap: round;\n  vector-effect: non-scaling-stroke;\n  filter: drop-shadow(0 1px 1.5px color-mix(in srgb, currentColor 18%, transparent));\n}\n\n.dbp_sparkArea {\n  fill: color-mix(in srgb, var(--dsw-alias-label-tertiary) 13%, transparent);\n  stroke: none;\n  /* 面积向基线淡出：实心色块会让「跌」看起来像一整块警示区，\n     渐隐之后读起来才是「线下方的一层影子」。不支持 mask 的环境会退回实心填充。 */\n  mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.55), rgba(0, 0, 0, 0.06));\n}\n\n/* 余额在涨（充值）用 success 色，在跌（消耗）用 warning 色。 */\n.dbp_trend[data-tone='up'] .dbp_sparkLine {\n  stroke: var(--dbp-ok);\n}\n\n.dbp_trend[data-tone='up'] .dbp_sparkArea {\n  fill: color-mix(in srgb, var(--dbp-ok) 15%, transparent);\n}\n\n.dbp_trend[data-tone='down'] .dbp_sparkLine {\n  stroke: var(--dbp-warn);\n}\n\n.dbp_trend[data-tone='down'] .dbp_sparkArea {\n  fill: color-mix(in srgb, var(--dbp-warn) 13%, transparent);\n}\n\n.dbp_trendFoot {\n  display: flex;\n  justify-content: space-between;\n  margin-top: 2px;\n  padding: 0 2px;\n  color: var(--dsw-alias-label-tertiary);\n  font-size: 10.5px;\n  line-height: 15px;\n  font-variant-numeric: tabular-nums;\n}\n\n/* ---------------------------------------------------------------- 计费时段 */\n\n/*\n * 状态行徽章上的时段标签。10.5px 是「比徽章数字小一档、但仍看得清」的尺寸。\n *\n * 底色只用一成多的透明度、外面再补一圈同色 24% 的发丝描边：档位色（绿/橙/红）\n * 说的是「钱还够不够」，时段色说的是「这个价贵不贵」，两件事不该混成一片\n * 抢注意力的色块。描边让标签在浅色底上仍有边界，但不加第二块实色。\n * 颜色取自 `:root` 的 `--dbp-peak` / `--dbp-offpeak`（面板 portal 到 body，\n * 变量挂在 `.dbp_root` 上的话面板里的徽标会取不到）。\n */\n.dbp_tariff {\n  flex: none;\n  padding: 0 6px;\n  border-radius: 999px;\n  border: 1px solid color-mix(in srgb, currentColor 24%, transparent);\n  font-size: 10.5px;\n  line-height: 15px;\n  font-weight: 500;\n  letter-spacing: 0.02em;\n  white-space: nowrap;\n}\n\n.dbp_root[data-tariff='peak'] .dbp_tariff {\n  color: var(--dbp-peak);\n  background-color: color-mix(in srgb, var(--dbp-peak) 12%, transparent);\n}\n\n.dbp_root[data-tariff='off-peak'] .dbp_tariff {\n  color: var(--dbp-offpeak);\n  background-color: color-mix(in srgb, var(--dbp-offpeak) 12%, transparent);\n}\n\n/* 面板里的时段行：一枚徽标 + 一句结论，排在金额明细与档位提示之间。 */\n.dbp_tariffRow {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  margin: 12px 0 0 3px;\n}\n\n.dbp_tariffBadge {\n  flex: none;\n  padding: 0 6px;\n  border-radius: 999px;\n  border: 1px solid color-mix(in srgb, currentColor 24%, transparent);\n  font-size: 11px;\n  line-height: 16px;\n  font-weight: 500;\n  letter-spacing: 0.02em;\n  white-space: nowrap;\n}\n\n.dbp_tariffBadge[data-tariff='peak'] {\n  color: var(--dbp-peak);\n  background: color-mix(in srgb, var(--dbp-peak) 12%, transparent);\n}\n\n.dbp_tariffBadge[data-tariff='off-peak'] {\n  color: var(--dbp-offpeak);\n  background: color-mix(in srgb, var(--dbp-offpeak) 12%, transparent);\n}\n\n/* 徽标后面那句结论：长句要能换行，因此允许收缩（flex 默认 min-width:auto 会撑破面板）。 */\n.dbp_tariffNote {\n  min-width: 0;\n  color: var(--dsw-alias-label-secondary);\n  font-size: 11.5px;\n  line-height: 17px;\n}\n\n/*\n * 时段明细（倒计时 / 本段区间 / 价格 / 峰谷预估 / 日历）。\n *\n * 左边那条 2px 竖轨把这五六行收成「同一段信息」，而不是散落在面板里的一堆小字；\n * 竖轨用中性色，不参与档位/时段的配色。日历覆盖行是诊断信息，比其余行再淡一档。\n */\n.dbp_tariffMeta {\n  margin: 0 0 0 3px;\n  padding: 3px 0 3px 10px;\n  border-left: 2px solid var(--dbp-rail);\n  color: var(--dsw-alias-label-tertiary);\n  font-size: 11.5px;\n  line-height: 17px;\n  font-variant-numeric: tabular-nums;\n}\n\n.dbp_tariffRow + .dbp_tariffMeta {\n  margin-top: 6px;\n}\n\n.dbp_tariffMeta[data-balance-tariff-calendar] {\n  font-size: 10.5px;\n  opacity: 0.8;\n}\n\n.dbp_topUp {\n  box-sizing: border-box;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 100%;\n  height: 34px;\n  margin-top: 12px;\n  border: 1px solid color-mix(in srgb, var(--dsw-alias-brand-text, var(--dsw-alias-state-business-primary)) 30%, transparent);\n  border-radius: 10px;\n  background: color-mix(in srgb, var(--dsw-alias-brand-text, var(--dsw-alias-state-business-primary)) 7%, transparent);\n  color: var(--dsw-alias-brand-text, var(--dsw-alias-state-business-primary));\n  font-size: 12.5px;\n  font-weight: 500;\n  text-decoration: none;\n  transition: background-color 0.15s ease, border-color 0.15s ease;\n}\n\n.dbp_topUp:hover {\n  background: color-mix(in srgb, var(--dsw-alias-brand-text, var(--dsw-alias-state-business-primary)) 13%, transparent);\n  border-color: color-mix(in srgb, var(--dsw-alias-brand-text, var(--dsw-alias-state-business-primary)) 42%, transparent);\n}\n\n.dbp_topUp:active {\n  background: color-mix(in srgb, var(--dsw-alias-brand-text, var(--dsw-alias-state-business-primary)) 18%, transparent);\n}\n\n.dbp_topUp:focus-visible {\n  outline: 2px solid var(--dsw-focus-ring-color, var(--dsw-alias-state-business-primary));\n  outline-offset: 2px;\n}\n\n/* ---------------------------------------------------------------- 设置行 */\n\n/*\n * 版式对齐宿主「设置 → 常规」里的行：上下 16px 内边距、底部 0.5px 分隔线、\n * 左侧标题 14px + 描述 12px、右侧控件。最后一行由宿主的\n * `[data-slot] > :last-child { border-bottom: none }` 处理，这里不用管。\n */\n.dbp_setRoot {\n  display: flex;\n  flex-direction: column;\n  width: 100%;\n}\n\n.dbp_setHead {\n  padding: 4px 0 12px;\n}\n\n.dbp_setHeadTitle {\n  font-size: 14px;\n  font-weight: 600;\n}\n\n/* 计费时段三行前面的分组说明：与根标题同版式，但用一条发丝线把它与上一组分开（v1.3）。 */\n.dbp_setGroup {\n  margin-top: 8px;\n  padding: 18px 0 4px;\n  border-top: 1px solid var(--dbp-hairline);\n}\n\n.dbp_setGroupTitle {\n  font-weight: 600;\n}\n\n.dbp_setRow {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 24px;\n  padding: 15px 0;\n  border-bottom: 1px solid var(--dsw-alias-border-l1);\n}\n\n.dbp_setRow[data-disabled='true'] {\n  opacity: 0.6;\n}\n\n.dbp_setCopy {\n  min-width: 0;\n}\n\n.dbp_setTitle {\n  color: var(--dsw-alias-label-primary);\n  font-size: 14px;\n  line-height: 20px;\n}\n\n.dbp_setDescription {\n  margin-top: 4px;\n  color: var(--dsw-alias-label-secondary);\n  font-size: 12px;\n  line-height: 18px;\n}\n\n.dbp_setControl {\n  display: flex;\n  flex: none;\n  align-items: center;\n  gap: 8px;\n}\n\n.dbp_setPair {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.dbp_setNotice {\n  margin-bottom: 4px;\n  padding: 8px 12px;\n  border-radius: 8px;\n  border-left: 2px solid var(--dbp-warn);\n  background: color-mix(in srgb, var(--dbp-warn) 11%, transparent);\n  color: var(--dbp-warn);\n  font-size: 12px;\n  line-height: 18px;\n}\n\n.dbp_select,\n.dbp_number {\n  box-sizing: border-box;\n  height: 32px;\n  padding: 0 8px;\n  border: 1px solid var(--dsw-alias-border-l3);\n  border-radius: 8px;\n  background: var(--dsw-specific-input-major, var(--dsw-alias-bg-layer-1));\n  color: var(--dsw-alias-label-primary);\n  font-family: inherit;\n  font-size: 13px;\n  font-variant-numeric: tabular-nums;\n  transition: border-color 0.15s ease, background-color 0.15s ease;\n}\n\n.dbp_select {\n  min-width: 168px;\n  max-width: 260px;\n}\n\n.dbp_number {\n  width: 72px;\n  text-align: right;\n}\n\n.dbp_select:hover,\n.dbp_number:hover {\n  border-color: var(--dsw-alias-border-l4);\n}\n\n.dbp_select:focus-visible,\n.dbp_number:focus-visible {\n  outline: 2px solid var(--dsw-focus-ring-color, var(--dsw-alias-state-business-primary));\n  outline-offset: 1px;\n}\n\n.dbp_check {\n  display: inline-flex;\n  align-items: center;\n}\n\n.dbp_check input {\n  width: 16px;\n  height: 16px;\n  margin: 0;\n  accent-color: var(--dsw-alias-state-business-primary);\n  cursor: pointer;\n}\n\n.dbp_setFoot {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding-top: 14px;\n}\n\n.dbp_setButton {\n  box-sizing: border-box;\n  height: 32px;\n  padding: 0 14px;\n  border: 1px solid var(--dsw-alias-border-l3);\n  border-radius: 8px;\n  background: 0 0;\n  color: var(--dsw-alias-label-primary);\n  font-family: inherit;\n  font-size: 13px;\n  cursor: pointer;\n  transition: background-color 0.15s ease, border-color 0.15s ease;\n}\n\n.dbp_setButton:hover {\n  background: var(--dsw-alias-interactive-bg-hover);\n}\n\n.dbp_setButton:focus-visible {\n  outline: 2px solid var(--dsw-focus-ring-color, var(--dsw-alias-state-business-primary));\n  outline-offset: 1px;\n}\n\n.dbp_setHint {\n  color: var(--dsw-alias-label-tertiary);\n  font-size: 12px;\n  line-height: 18px;\n}\n\n/* 紧凑模式：徽章不带币种符号，去掉一点横向内边距。 */\n.dbp_root[data-compact='true'] .dbp_trigger {\n  padding: 2px 8px;\n}\n\n/* ---------------------------------------------------------------- 提醒卡片 */\n\n/*\n * 只在宿主 primitives 的 Toast 拿不到时才出现（见 alert-toast.js）。\n * 宿主 Toast 自己 portal 到 body 并占 z-index:1100；这张兜底卡片挂在\n * `shell.overlay` 里（z-index:20 的浮层，子元素自带 pointer-events:auto），\n * 因此定位用 absolute 贴右下角即可，不必自己抬层级。\n */\n.dbp_alert {\n  position: absolute;\n  right: 16px;\n  bottom: 16px;\n  box-sizing: border-box;\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  max-width: min(420px, calc(100vw - 32px));\n  padding: 10px 12px;\n  border-radius: 12px;\n  background: var(--dsw-alias-toast-bg, var(--dsw-specific-menu));\n  color: var(--dsw-alias-toast-label, #fff);\n  box-shadow: var(--dsw-elevation-prominent);\n  font-size: 13px;\n  line-height: 20px;\n}\n\n.dbp_alertText {\n  min-width: 0;\n}\n\n.dbp_alertAction {\n  flex: none;\n  height: 26px;\n  padding: 0 10px;\n  border: 1px solid color-mix(in srgb, currentColor 40%, transparent);\n  border-radius: 8px;\n  background: 0 0;\n  color: inherit;\n  font-family: inherit;\n  font-size: 12px;\n  cursor: pointer;\n  transition: background-color 0.15s ease;\n}\n\n.dbp_alertAction:hover {\n  background: rgba(255, 255, 255, 0.14);\n}\n\n.dbp_alertAction:focus-visible {\n  outline: 2px solid var(--dsw-focus-ring-color, var(--dsw-alias-state-business-primary));\n  outline-offset: 1px;\n}\n\n.dbp_alert[data-level='low'] .dbp_alertAction {\n  color: var(--dbp-low);\n}\n\n/* ------------------------------------------------------------ 无障碍与降级 */\n\n/*\n * 动效降级：面板的展开动画只是点缀，关闭它不影响任何信息。\n * 徽章的 hover 过渡也一并去掉 —— 对前庭敏感的用户，颜色渐变不构成问题，\n * 但统一处理更可预测。\n */\n@media (prefers-reduced-motion: reduce) {\n  .dbp_trigger,\n  .dbp_refresh,\n  .dbp_topUp,\n  .dbp_alertAction {\n    transition: none;\n  }\n\n  .dbp_panel {\n    animation: none;\n  }\n}\n\n/*\n * 强制配色模式（Windows 高对比度、部分 Linux 主题）：color-mix 的颜色会被系统\n * 覆盖成 Canvas/CanvasText，淡底与阴影全部消失。这里补上实线边界，保证面板、\n * 按钮与时段竖轨在「没有颜色」的世界里仍然分得清层次。\n */\n@media (forced-colors: active) {\n  .dbp_panel,\n  .dbp_trend {\n    border: 1px solid CanvasText;\n    box-shadow: none;\n  }\n\n  .dbp_trigger,\n  .dbp_refresh,\n  .dbp_topUp,\n  .dbp_alertAction,\n  .dbp_tariff,\n  .dbp_tariffBadge {\n    border: 1px solid CanvasText;\n  }\n\n  .dbp_tariffMeta,\n  .dbp_stale {\n    border-left-color: CanvasText;\n  }\n\n  .dbp_spend {\n    background: Canvas;\n    border: 1px solid CanvasText;\n  }\n\n  .dbp_sparkLine {\n    stroke: CanvasText;\n    filter: none;\n  }\n\n  .dbp_sparkArea {\n    fill: none;\n  }\n}\n"
